<?php require 'includes/db.php'; $newCountries = ['Austria' => 'austria', 'Finland' => 'finland', 'Hungary' => 'hungary', 'Lithuania' => 'lithuania', 'Cyprus' => 'cyprus', 'Poland' => 'poland', 'Czech Republic' => 'czech-republic', 'Mauritius' => 'mauritius', 'Japan' => 'japan', 'Vietnam' => 'vietnam', 'Malta' => 'malta', 'China' => 'china', 'Belgium' => 'belgium', 'Georgia' => 'georgia', 'Croatia' => 'croatia', 'Latvia' => 'latvia', 'Luxembourg' => 'luxembourg']; foreach($newCountries as $name => $slug) { $stmt = $pdo->prepare('SELECT COUNT(*) FROM countries WHERE slug = ?'); $stmt->execute([$slug]); if($stmt->fetchColumn() == 0) { $stmt2 = $pdo->prepare('INSERT INTO countries (name, slug, is_active) VALUES (?, ?, 1)'); $stmt2->execute([$name, $slug]); echo 'Inserted ' . $name . PHP_EOL; } } $stmt3 = $pdo->query('DELETE t1 FROM countries t1 INNER JOIN countries t2 WHERE t1.id > t2.id AND t1.slug = t2.slug'); echo 'Duplicates removed. '; $stmt4 = $pdo->query('SELECT COUNT(*) FROM countries WHERE is_active = 1'); echo 'Total active countries: ' . $stmt4->fetchColumn();
